import { Sex } from '../babies/baby.models';

/** A measure of the WHO Child Growth Standards: weight-for-age (kg), length-for-age and head circumference-for-age (cm). */
export type GrowthMeasure = 'weight' | 'length' | 'head';

/** A WHO LMS row: Box-Cox power L, median M and coefficient of variation S. */
export interface Lms {
  l: number;
  m: number;
  s: number;
}

/** A measure's L, M and S columns, aligned with the reference's ages. */
export interface LmsTable {
  l: number[];
  m: number[];
  s: number[];
}

/** `public/reference/who-growth.json`, generated by `tools/who-growth.mjs` (spec 12). */
export interface GrowthReference {
  source: string;
  licence: string;
  ageDays: number[];
  girl: Record<GrowthMeasure, LmsTable>;
  boy: Record<GrowthMeasure, LmsTable>;
}

/** The 3rd, 15th, 50th, 85th and 97th percentile values at an age. */
export interface PercentileValues {
  p3: number;
  p15: number;
  p50: number;
  p85: number;
  p97: number;
}

/** The reference's last age, 5 years: nothing is drawn after it. */
export const REFERENCE_MAX_AGE_DAYS = 1826;

const Z: Record<keyof PercentileValues, number> = {
  p3: -1.88079,
  p15: -1.03643,
  p50: 0,
  p85: 1.03643,
  p97: 1.88079,
};

/** L, M and S at an age in days, interpolated linearly between two rows; null outside the reference. */
export function lmsAt(table: LmsTable, ageDays: readonly number[], age: number): Lms | null {
  if (age < 0 || age > REFERENCE_MAX_AGE_DAYS || age > ageDays[ageDays.length - 1]) {
    return null;
  }
  const upper = ageDays.findIndex((a) => a >= age);
  const row = (i: number): Lms => ({ l: table.l[i], m: table.m[i], s: table.s[i] });
  if (ageDays[upper] === age || upper === 0) {
    return row(upper);
  }
  const lower = upper - 1;
  const t = (age - ageDays[lower]) / (ageDays[upper] - ageDays[lower]);
  const mix = (key: keyof Lms) => table[key][lower] + (table[key][upper] - table[key][lower]) * t;
  return { l: mix('l'), m: mix('m'), s: mix('s') };
}

/** The value at z standard deviations: M × (1 + L × S × z)^(1/L), or M × exp(S × z) when L is 0. */
export function percentileValue({ l, m, s }: Lms, z: number): number {
  return l === 0 ? m * Math.exp(s * z) : m * (1 + l * s * z) ** (1 / l);
}

/** A sex's five percentile values of a measure at an age in days; null outside the reference. */
export function percentilesAt(
  reference: GrowthReference,
  sex: Exclude<Sex, 'unspecified'>,
  measure: GrowthMeasure,
  age: number,
): PercentileValues | null {
  const lms = lmsAt(reference[sex][measure], reference.ageDays, age);
  if (!lms) {
    return null;
  }
  return {
    p3: percentileValue(lms, Z.p3),
    p15: percentileValue(lms, Z.p15),
    p50: percentileValue(lms, Z.p50),
    p85: percentileValue(lms, Z.p85),
    p97: percentileValue(lms, Z.p97),
  };
}
